#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 5 + 1; std::set<std::pair<int,int>> e; int m = n > 1 ? r() % (n * (n - 1) / 2 + 1) : 0; while ((int)e.size() < m) { int a = r() % n + 1, b = r() % n + 1; if (a != b) e.insert({std::min(a, b), std::max(a, b)}); } std::vector<int> a(n), b(n); for (auto& x : a) x = r() % 5; if (r() % 2) { b = a; for (int k = 0; k < 4; k++) { int i = r() % n, j = r() % n; if (b[i]) { b[i]--; b[j]++; } } } else for (auto& x : b) x = r() % 5; printf("%d %d\n", n, m); for (int x : a) printf("%d ", x); puts(""); for (int x : b) printf("%d ", x); puts(""); for (auto [p, q] : e) printf("%d %d\n", p, q); }
